// Host dependencies of the 2.42304.0 low-disk toast (cov0-04; src/generated/r3b-settings/**, generated by
// scripts/extract-r3b-settings.mjs). The toast itself (cf615570b DesktopLowDiskToast: the 10 GB threshold, the 7-day
// reminder record, clearing above 10 GB and forgetting above 20 GB, mount + window focus checks), its byte label
// (shared-3 ZC) and the main process's free-space reading (YAr) are original; only the runtime services the official
// shell supplies are answered here.
import { createContext, isValidElement, useContext, useMemo } from 'react';
import { useStartIntl } from './source-code-start-adapters.jsx';

// vendor-intl q / Gt (react-intl useIntl / FormattedMessage) over the local catalog: the English message is looked up
// in zh-CN by t(); formatNumber (the byte label) uses the UI locale.
export { useStartIntl as useIntl, StartMessage as FormattedMessage } from './source-code-start-adapters.jsx';

// shared-0 tx (`globalThis["claude.web"]?.DeviceStorage`): the desktop bridge's storage namespace. The toast only calls
// getFreeDiskSpace, and the official mount (shared-23 O6) renders nothing without it, so the method exists only while
// the preload's desktop bridge does (not in SSR, tests without a stub, or a plain browser). Main answers
// `desktop-free-disk-space` with the original YAr statfs of userData (electron/generated/r3b-settings-free-disk.cjs),
// null when it cannot be read: the same `await FOa() ?? null` as BOa.
const freeBytes = value => (typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : null);
export const DeviceStorage = Object.freeze({
  get getFreeDiskSpace() {
    const call = globalThis.window?.desktop?.call;
    return typeof call === 'function' ? () => Promise.resolve(call('desktop-free-disk-space')).then(freeBytes) : undefined;
  },
});

// shared-52 Sj (exported `Ya`): useContext(ErrorsProvider) -> { addWarning, clearToast, … }. The host's toast store
// (toast-store.mjs createToastStore, the store SourceToastProvider renders) is handed in by the mount
// (source-r3b-settings-low-disk.jsx). addWarning(message, {timeout, uniqueKey, action}) pushes a warning toast and
// returns its id (the store's `key` is the official uniqueKey: a live toast with the same key is updated in place);
// clearToast(id) closes it.
//
// Host difference: the official action slot takes a ReactNode (here the original CDS Button, sm secondary, whose
// onClick clears the toast and opens storage). The host toast's slot takes {label, onClick} and renders its own sm
// secondary SourceSettingsButton, so the element is read for its onClick and its label (a FormattedMessage formatted
// with the same intl, or plain text). An action that is neither is dropped rather than shown as something else.
export const LowDiskToastStore = createContext(null);
function toastAction(action, intl) {
  if (!isValidElement(action) || typeof action.props?.onClick !== 'function') return undefined;
  const { children, onClick } = action.props;
  const label = typeof children === 'string' ? children
    : isValidElement(children) && typeof children.props?.defaultMessage === 'string'
      ? intl.formatMessage({ id: children.props.id, defaultMessage: children.props.defaultMessage }, children.props.values) : null;
  return typeof label === 'string' && label ? { label, onClick } : undefined;
}
export function useErrors() {
  const store = useContext(LowDiskToastStore), intl = useStartIntl();
  if (!store) throw Error('Must be called within ErrorsProvider');
  return useMemo(() => ({
    addWarning: (message, { timeout, uniqueKey, action } = {}) =>
      store.add(message, { variant: 'warning', timeout, key: uniqueKey, action: toastAction(action, intl) }),
    clearToast: id => { if (id !== null && id !== undefined) store.close(id); },
  }), [store, intl]);
}
